  "user": {
    "bio": "Temporary bio"
  }
}
HTTP 200
[Asserts]
jsonpath "$.user.bio" == "Temporary bio"

# Update user bio to null - should accept for nullable field
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "bio": null
  }
}
HTTP 200
[Asserts]
jsonpath "$.user.bio" == null

