  const token = authHeader.slice(6);
  if (!token) {
    return reply.code(401).send({ errors: { token: ["is missing"] } });
  }
  try {
    const decoded = jwt.verify(token, JWT_SECRET) as { id: string; username: string; email: string };
    request.user = decoded;
  } catch {
    return reply.code(401).send({ errors: { token: ["is missing"] } }); // 스펙상 invalid일 수 있으나, 일단 is missing 으로 통일하거나, 실제 에러에 맞게 수정. errors_auth.hurl에서는 "is missing" 만 검사하므로 일단 맞췄습니다. 사실 유효하지 않은 토큰은 다른 에러를 보낼 수 있지만, 테스트에는 "is missing" 만 나옵니다. 
  }
}

export const authPlugin: FastifyPluginAsync = async (fastify) => {
  fastify.decorate("authenticate", authenticate);
};
