import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";
import bcrypt from "bcryptjs";

// Hurl 스펙 에러 포맷: {"errors": {"field": ["message"]}}
function fieldError(field: string, message: string) {
  return { errors: { [field]: [message] } };
}

// 빈 문자열을 null로 정규화 (Bio, Image 필드 전용 - Hurl 테스트 81~92줄, 167~177줄 대응)
function normalizeNullable(value: string | null | undefined): string | null {
  if (value === "" || value === undefined) {
    return null;
  }
  return value;
}

// 비밀번호 검증 (Hurl 테스트 176~204줄 대응: 빈 문자열, null, 8자 미만 거부)
function validatePassword(password: unknown): string | null {
  if (password === null || password === undefined || password === "") {
    return "can't be blank";
  }
  if (typeof password !== "string") {
    return "can't be blank";
  }
  if (password.length < 8) {
    // 8자 미만 거부 (Hurl 테스트: "short7c" → 422 기대)
    return "can't be blank";
  }
  return null;
}

export async function userRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/user: 현재 사용자 정보 조회
  app.get("/api/user", { preHandler: app.authenticate }, async (request: FastifyRequest, reply: FastifyReply) => {
    const userId = (request as any).user?.id;
    if (!userId) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) {
      return reply.code(404).send({ message: "User not found" });
    }

    return {
      user: {
        username: user.username,
        email: user.email,
        bio: user.bio ?? null,
        image: user.image ?? null,
        token: user.token ?? null,
      },
    };
  });

  // PUT /api/user: 현재 사용자 정보 수정
  app.put("/api/user", { preHandler: app.authenticate }, async (request: FastifyRequest, reply: FastifyReply) => {
    const userId = (request as any).user?.id;
    if (!userId) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const updates = (request as any).body;
    const data: Record<string, unknown> = {};

    // username 업데이트 검증 (Hurl 테스트 142~150줄 대응)
    if (updates?.username !== undefined) {
      if (updates.username === "" || updates.username === null) {
        return reply.code(422).send(fieldError("username", "can't be blank"));
      }
      data.username = updates.username;
    }

    // email 업데이트 검증 (Hurl 테스트 132~141줄 대응)
    if (updates?.email !== undefined) {
      if (updates.email === "" || updates.email === null) {
        return reply.code(422).send(fieldError("email", "can't be blank"));
      }
      data.email = updates.email;
    }

    // password 업데이트 검증 (Hurl 테스트 172~204줄 대응)
    if (updates?.password !== undefined) {
      const pwdError = validatePassword(updates.password);
      if (pwdError) {
        return reply.code(422).send(fieldError("password", pwdError));
      }
      data.password = await bcrypt.hash(updates.password as string, 10);
    }

    // bio 업데이트 (빈 문자열 → null, 명시적 null 허용 - Hurl 테스트 81~129줄 대응)
    if (updates?.bio !== undefined) {
      data.bio = normalizeNullable(updates.bio);
    }

    // image 업데이트 (빈 문자열 → null, 명시적 null 허용 - Hurl 테스트 167~207줄 대응)
    if (updates?.image !== undefined) {
      data.image = normalizeNullable(updates.image);
    }

    // 토큰 재생성 (프로필 업데이트 시마다 새 토큰 발급 - Hurl 테스트 217~231줄 대응)
    const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) {
      return reply.code(404).send({ message: "User not found" });
    }
    const newToken = jwt.sign(
      { id: userId, username: data.username ?? user.username, email: data.email ?? user.email },
      JWT_SECRET,
      { expiresIn: "7d" }
    );
    data.token = newToken;

    const updated = await prisma.user.update({
      where: { id: userId },
      data,
    });

    return {
      user: {
        username: updated.username,
        email: updated.email,
        bio: updated.bio ?? null,
        image: updated.image ?? null,
        token: updated.token ?? null,
      },
    };
  });
}
